insert into _kapisma_tr (id, yerel, eski, yeni) values
  ('8800d2fb-b58b-5a97-aeac-15270193a913', 'offline_6059', '"hewran": diğer giysilerin üstüne giyilen uzun üstlük (aba).', 'Hewran, öteki giysilerin üstüne giyilen uzun dış giysidir; günlük giysi katı değil, en üstteki örtü katıdır.'),
  ('b0a0fca8-aa88-5f74-a85a-16119b8655eb', 'offline_6093', '"tûrik": yiyecek taşımak için dokunan torba.', 'Tûrik dokuma bir torbadır; yolda ya da tarlada ekmek ve azık taşımak için kullanılır.'),
  ('a7f1b481-b1e1-5559-975e-c29ae42be8b1', 'offline_6117', '"nanê tenûrê": tandırda pişirilen geleneksel ekmek.', 'Nanê tenûrê, tandırın (tenûr) iç duvarına yapıştırılarak pişirilen ince ekmektir; adı da pişirildiği ocaktan gelir.'),
  ('4e28dece-a151-5b47-8d78-2abe2bc43d93', 'offline_6136', '"koçerî": göçer yaşam tarzı ve dans ritmi.', 'Koçerî, yaz yaylası (zozan) ile kışlık (germiyan) arasında mevsimlik göçe dayanan yaşam biçimidir; aynı adla anılan bir govend ritmi de vardır.'),
  ('992b5825-d7da-528f-84c0-11d4b53b4e4a', 'offline_6189', '"cîranî": komşuluk ve toplumsal yardımlaşma.', 'Cîranî, "cîran" (komşu) sözcüğünden gelir; komşuluk ilişkisini ve komşular arası yardımlaşmayı anlatır.'),
  ('056a6a6f-6811-5da1-8660-f4e31476c213', 'offline_6457', '"şabaş": müzisyenlere bahşiş atma geleneği.', 'Şabaş, düğün ve şenliklerde para ya da armağan verme geleneğidir; birçok yörede çalgıcılara ve dengbêjlere verilen bahşişi anlatır.'),
  ('d82f6053-3c83-5856-a18a-1fcae2184ee1', 'offline_6465', '"sersal": Kürt halk takviminde yılbaşı kutlaması.', 'Sersal, "ser" (baş) ve "sal" (yıl) sözcüklerinden oluşur; halk takviminde yeni yılın başlangıcını kutlamayı anlatır.'),
  ('536d2683-b5d1-56db-9934-3c015ffb93d5', 'offline_6533', '"masal anlatımı": kuşaktan kuşağa aktarılan anlatı.', 'Masallar sözlü gelenekte kuşaktan kuşağa anlatılarak aktarılır; zamanla yazıya geçirilerek de korunur.'),
  ('c1900627-a209-52f4-a198-d4b85eb58581', 'offline_6538', '"şevbêrk": kış gecelerinde yapılan sohbet toplantıları.', 'Şevbêrk, uzun kış gecelerinde komşuların bir evde toplanıp masal, kilam ve sohbetle vakit geçirdiği toplantıdır.'),
  ('6e9f8007-63ad-5c56-b456-42cb3b7a3d93', 'offline_6730', '"serpêhatî": yaşanmış ilginç olayların anlatımı.', 'Serpêhatî, birinin başından geçmiş, yaşanmış olayları anlatan anlatıdır; hayal ürünü masaldan bu yönüyle ayrılır.'),
  ('aaadbd89-176c-5541-aee0-4a3785b2729f', 'offline_6835', '"qutik": geleneksel Kürt yeleği veya giysisi.', 'Qutik, geleneksel giyimde yelek ya da üst giysi için kullanılan addır; öteki seçenekler giysi değil, başka kültür öğeleridir.'),
  ('8ff79e66-cf2b-526a-b1ad-3c7413d73fc8', 'offline_6841', '"reşmal": siyah keçi kılından yapılan çadır.', 'Reşmal "kara ev" demektir: göçerlerin keçi kılından dokunan çadırıdır; kıl yağmurda şişerek su geçirmez.'),
  ('b74aada5-767d-5b34-983c-c53c92f8b4e4', 'offline_7066', '"Dersim 1937": 1937-38 Dersim harekâtı, çatışmalar ve kitlesel öldürmeler.', 'Dersim 1937–38, devletin bölgede yürüttüğü askerî harekâtı ve bu sırada yaşanan toplu öldürme ve sürgünleri anlatır.'),
  ('eecba717-363e-569d-9e6e-3a90d9bae4a2', 'offline_7145', '"Şeyh Said": 1925 Şeyh Said İsyanı''nın başlıca lideri.', 'Şeyh Said, 1925 ayaklanmasının lideriydi; ayaklanmanın dinî ve Kürt ulusal boyutları tarihçilerce farklı değerlendirilir. Ayaklanma bastırıldı ve Şeyh Said aynı yıl Diyarbakır''da idam edildi.'),
  ('a1f9f20b-0554-5687-9664-e06b387ff657', 'offline_7151', '"Baban Emirliği": Süleymaniye merkezli güçlü Kürt prensliği.', 'Baban Beyliği, merkezi Silêmanî (Süleymaniye) olan güçlü bir Kürt beyliğiydi; kent 1784''te Babanlar tarafından kuruldu.'),
  ('06d3f7a1-e623-5400-a584-b08308cb429d', 'offline_7223', '"Kasr-ı Şirin Antlaşması": Osmanlı ve Safevi sınırını belirleyen antlaşma.', 'Kasr-ı Şirin Antlaşması (1639) Osmanlı–Safevi sınırını düzenledi ve Kürtlerin yaşadığı bölgelerin iki devlet arasındaki paylaşımını büyük ölçüde pekiştirdi.'),
  ('ae03650d-527b-5848-867f-cffc9187f457', 'offline_7249', '"Şeyh Mahmud Berzenci": Irak''ta kendini Kürdistan kralı ilan eden lider.', 'Şeyh Mahmud Berzenci, 1920''lerde Süleymaniye''de kendini Kürdistan kralı (hükümdarı) ilan etti ve İngiliz yönetimine karşı direndi.'),
  ('51cf256f-3581-5fcb-9f08-0229341c4780', 'offline_7300', '"Mela Mahmude Bayazidi": Kürt örf adetlerini derleyen ilk araştırmacı.', 'Mela Mehmûdê Bazîdî, 19. yüzyılda Kürt örf ve âdetlerini Kürtçe olarak derleyen öncü eseri hazırladı; çalışma Rus diplomat Aleksandr Jaba''nın teşvikiyle yazıldı.'),
  ('1a22fe3e-1366-5098-8d04-798bc1e8e936', 'offline_7417', '"şîroveya dîrokî": kanıtlardan anlam çıkarma.', 'Tarihî yorum, kaynaklardaki kanıtları karşılaştırıp onlardan anlam ve sonuç çıkarmaktır; yalnızca olayları sıralamak yorum değildir.'),
  ('cc708a55-98ca-53f1-b6c8-208f802c7df6', 'offline_7474', '"sözlü tarih": tanıklık ve anlatılarla geçmişi anlama yöntemi.', 'Dîroka devkî (sözlü tarih), geçmişi olayları yaşamış ya da duymuş kişilerin sözlü tanıklıkları üzerinden araştırır; bu tanıklıklar yazılı belgeler ve öteki kaynaklarla birlikte değerlendirilir.'),
  ('8614c98b-9514-5398-9501-ba79056f87e4', 'offline_7497', '"Mustafa Barzani": Kürt ulusal hareketinin askerî ve siyasî liderlerinden biri.', 'Mustafa Barzani (1903–1979), Güney Kürdistan''daki Kürt hareketinin uzun yıllar askerî ve siyasi önderliğini yaptı; Mahabad Cumhuriyeti''nin ordusunda da komutandı.'),
  ('5c89b78c-9abb-51c9-b8f7-2d05f939e98b', 'offline_7507', '"göç": toplulukların yer değiştirmesi.', 'Göç, insan topluluklarının yaşadığı yeri savaş, geçim ya da baskı gibi nedenlerle değiştirmesidir; geçici ya da kalıcı olabilir.'),
  ('43d87741-9576-5920-ad2e-10a58a68ce2d', 'offline_7605', '"birincil kaynak": Döneminden kalan belge veya nesne (birincil kaynak).', 'Birincil kaynak, araştırılan konuya doğrudan tanıklık eden ya da özgün veri sunan kaynaktır; dönemin belgeleri, nesneleri ve tanık anlatıları buna örnektir.'),
  ('f580690b-21d1-5b8a-9f80-4e1778aeb76f', 'offline_7643', '"Mikdat Mithat Bedirxan": 1898''de ilk Kürtçe gazete Kurdistan''ı çıkaran kişi.', 'Mikdat Mithat Bedirxan, ilk Kürtçe gazete olan Kurdistan''ı 22 Nisan 1898''de Kahire''de yayımlamaya başladı; bu tarih Kürt basın günü olarak anılır.'),
  ('c6a33f83-73cc-52e7-ab5f-a1440cc5d626', 'offline_7763', '"Bohtan Emirliği": Cizre merkezli önemli Kürt beyliği.', 'Botan Beyliği''nin merkezi Cizre''ydi (Cizîra Botan); son büyük beyi Bedirxan Bey 1847''de Osmanlı''ya yenildi.'),
  ('4cbea941-2a07-5c24-8b0b-7576468bc76a', 'offline_7798', '"Îhsan Nûrî Paşa": Hoybun cemiyeti adına askeri liderlik yapan subay.', 'Îhsan Nûrî Paşa, Hoybûn cemiyetinin desteklediği Ağrı (Ararat) ayaklanmasının (1927–1930) askerî komutanıydı.'),
  ('ba592679-02c6-5cc1-818b-22f10dcdca19', 'offline_7852', '"Kovara Hawar": Latin alfabesiyle basılan ilk Kürtçe dergi.', 'Hawar dergisi 1932''de Şam''da Celadet Alî Bedirxan tarafından çıkarıldı; Latin harfli Kurmancî alfabesini yaydı.'),
  ('275b9299-3d48-591a-9ea6-492bc702f907', 'offline_7905', '"Kampanyaya Enfalê": Irak rejimi tarafından Kürtlere yönelik soykırım.', 'Enfal, Irak''taki Baas rejiminin 1988''de Kürtlere karşı yürüttüğü kampanyadır; köyler yıkıldı, on binlerce insan öldürüldü. Birçok ülke ve kurum bunu soykırım olarak tanır.'),
  ('c362c08b-fe14-517f-8250-4cab07423e09', 'offline_8023', '"Heskîf": Dicle nehri üzerinde yer alan binlerce yıllık tarihi kent.', 'Heskîf (Hasankeyf), Dicle kıyısında kayalara oyulmuş mağara yerleşimleriyle bilinen çok eski bir kenttir; Ilısu Barajı''nın suları eski kentin büyük bölümünü 2020''de kapladı.'),
  ('181dcca2-6fa9-5d45-8b2c-3c46c4cedb88', 'offline_8141', '"Derbendihan gölü": Diyala nehri üzerinde kurulmuş baraj gölü.', 'Derbendîxan Gölü, Diyala (Sîrwan) Nehri üzerine kurulan barajın oluşturduğu yapay göldür; doğal göl değildir.'),
  ('3ac95f40-e4d2-509a-ac6b-2316aaafff60', 'offline_8200', '"Siverek ovası": Karacadağ lavlarının oluşturduğu taşlık plato.', 'Siverek Ovası (Deşta Sêwregê), Karacadağ''dan akan bazalt lavlarının örttüğü taşlık bir düzlüktür; bu yüzden toprağı taşlıdır.'),
  ('d5fef95b-da03-593d-80fb-c7853af3eaa1', 'offline_8255', '"Zagros sıradağları": Kürdistan coğrafyasını baştan başa bölen dağlar.', 'Zagros sıradağları kuzeybatı–güneydoğu doğrultusunda uzanır ve Kürdistan coğrafyasının omurgasını oluşturur.'),
  ('366222d8-55ed-53e3-ab3a-98012fece2e6', 'offline_8384', '"Hewlêr ovası": Güney Kürdistan''ın verimli tarım ovalarından biri.', 'Hewlêr (Erbil) Ovası, Büyük ve Küçük Zap arasında uzanan verimli bir düzlüktür; tahıl tarımıyla bilinir.'),
  ('c33e360d-6b01-535b-9d45-cc6a5899f8f8', 'offline_8480', '"Karacadağ": Diyarbakır ovasında yer alan yayvan bazaltik volkan.', 'Karacadağ (Qerejdax), Diyarbakır ile Urfa arasında yayılan geniş ve alçak bir kalkan volkanıdır; çevresindeki bazalt taşlar Amed surlarında da kullanılmıştır.'),
  ('bc8f62d2-023f-5ff9-9866-269807506092', 'offline_8523', '"Dicle nehri": Diyarbakır surlarının altından geçen nehir.', 'Dicle, Diyarbakır''ın tarihî surlarının aşağısındaki vadiden akar; Hevsel Bahçeleri surlarla nehir arasındaki alandadır.'),
  ('cc221d3b-f542-54d4-9969-69e9d9df2f36', 'offline_8532', '"Dokan gölü": Süleymaniye yakınlarında yer alan yapay baraj gölü.', 'Dokan Gölü, Küçük Zap üzerine kurulan barajın oluşturduğu yapay göldür ve Süleymaniye iline bağlıdır.'),
  ('85e345da-da12-5082-90cc-cced11451cb9', 'offline_8539', '"Kürdistan iklimi": karasal ve dağlık alanlarda soğuk kışlar.', 'Kürdistan''ın büyük bölümünde karasal iklim hâkimdir: yükseklik ve denizden uzaklık nedeniyle kışlar soğuk ve karlı, yazlar sıcak ve kurak geçer.'),
  ('41665ecf-07e3-5ff9-8e6d-aa347103af83', 'offline_8603', '"Hazar gölü": Elazığ sınırlarında yer alan tektonik göl.', 'Hazar Gölü, Elazığ''da Doğu Anadolu Fay Hattı üzerinde oluşmuş tektonik bir göldür; Dicle bu göl yöresinden doğar.'),
  ('eea6815d-efe3-564d-a823-173738e4f778', 'offline_8950', '"Dokan gölü": Süleymaniye yakınlarında yer alan yapay baraj gölü.', 'Dokan Gölü, Küçük Zap üzerindeki Dokan Barajı ile oluşmuş yapay göldür; Süleymaniye yakınındadır.'),
  ('2fe04d59-bcbe-523a-bf78-61f211522280', 'offline_9132', '"Habur çayı": Türkiye ve Irak sınırını çizen Dicle kolu.', 'Habur Çayı, Zaho yakınından geçip Dicle''ye karışan bir koldur; bir kesiminde Türkiye–Irak sınırını oluşturur.'),
  ('3778b742-5722-5f4b-b6fc-c60c0fa3f570', 'offline_9207', '"Ronahî dergisi": Şam''da Latin alfabesiyle çıkarılan edebi dergi.', 'Ronahî dergisi 1942–1945 arasında Şam''da Celadet Alî Bedirxan tarafından çıkarıldı; Hawar''ın kardeş yayınıydı ve resimliydi.'),
  ('5f0a48c4-22df-58a6-985e-971081806482', 'offline_9227', '"Cegerxwîn": modern Kürt şiirinin öncü toplumcu şairi.', 'Cegerxwîn (1903–1984), klasik biçimlerden de yararlanarak şiirinde halkın yaşamını, toplumsal hakları ve özgürlüğü işledi; modern toplumcu Kürt şiirinin öncülerinden sayılır.'),
  ('ff6ea5ed-7d02-518c-8737-82c3e09423ba', 'offline_9410', '"destana Memê Alan": Ehmedê Xanî''nin Mem û Zîn''e ilham aldığı halk destanı.', 'Memê Alan sözlü bir halk destanıdır; Ehmedê Xanî 1692''de yazdığı Mem û Zîn mesnevisinde bu anlatıdan yararlandı.'),
  ('c2532d7c-87e6-56a9-899f-53defea20d83', 'offline_9434', '"Riya Taza gazetesi": Erivan''da uzun yıllar basılan Kürtçe gazete.', 'Riya Taza, 1930''da Erivan''da yayımlanmaya başlayan Kürtçe gazetedir; yayını bir süre kesildikten sonra 1955''te yeniden başladı.'),
  ('4ddd8267-674e-562f-be9a-b11e699fb4de', 'offline_9456', '"Xanî Mektebi": Ehmedê Xanî''nin başlattığı edebi ve düşünsel ekol.', 'Xanî Mektebi, Ehmedê Xanî''nin Kürtçeyi bilim ve edebiyat dili yapma çabasından doğan ekoldür; Mem û Zîn''deki dil ve kimlik vurgusu bu düşüncenin temelidir.'),
  ('ba2759a3-1e8f-58a5-9b65-7c675166802a', 'offline_9552', '"Masture Erdelan": tarihte divan yazmış ilk Kürt kadın tarihçi ve şair.', 'Mestûre Erdelan (1805–1848), Erdelan Beyliği''nin tarihini yazdı ve şiirlerini divanda topladı; ilk Kürt kadın tarihçi olarak anılır.'),
  ('1512d71a-288b-5a23-80db-3b6968d2c79c', 'offline_9594', '"Nûbihara Biçûkan": Ehmedê Xanî tarafından yazılan ilk Kürtçe sözlük.', 'Nûbihara Biçûkan, Ehmedê Xanî''nin çocukların Arapça öğrenmesi için yazdığı manzum Arapça–Kürtçe sözlüktür; sözcükler ezberlenecek beyitler hâlinde verilir.'),
  ('421bf996-e228-5b7e-b029-32378213f3e5', 'offline_9625', '"Osman Sabri": modern Kürt hikayeciliğinin kurucu isimlerinden.', 'Osman Sebrî (1905–1993), Hawar çevresinde yetişen yazar ve şairdir; modern Kürt öykücülüğünün kurucu adlarından sayılır.'),
  ('8d92ec5b-8537-5cf0-99ad-fda48ab582e3', 'offline_9724', '"Hawar Ekolü": Kürt aydınlanmasını ve Latin alfabesini yayan edebi akım.', 'Hawar Ekolü, 1930–40''larda Bedirxan kardeşler çevresinde gelişti; Latin harfli Kurmancı yazı dilini ve Kürt aydınlanmasını yaydı.'),
  ('c50304aa-5a2e-573f-b066-16598ca81a59', 'offline_9778', '"Nalî": Soranice klasik şiirin Baban okulunun başlıca adlarından divan şairi.', 'Nalî, 19. yüzyılda Baban beyliği döneminde Soranice yazan divan şairidir; Soranî klasik şiirin kurucu adlarından sayılır.'),
  ('4343de02-d742-5b98-81a5-a309e00d0d0f', 'offline_10074', '"Dîwana Melayê Cizîrî": mistik aşk ve felsefe içeren meşhur şiir divanı.', 'Melayê Cizîrî''nin divanı tasavvufi aşkı ve felsefi düşünceyi işler; klasik Kurmancî şiirin en çok okunan eserlerindendir.'),
  ('b6180e9e-1460-56fd-b07f-409fcd93dc3c', 'offline_10314', '"serhad ezgileri": Kars, Ağrı ve Van yöresine özgü lirik müzik tarzı.', 'Serhad ezgileri Kars, Ağrı ve Van yöresinden gelir; uzun soluklu, lirik dengbêj söyleyişleriyle bilinir.'),
  ('11a79256-9ebb-5b2a-8cf5-10c39409d74b', 'offline_10320', '"dengbêjlik okulu": usta-çırak ilişkisiyle yürüyen müzikal aktarım.', 'Dengbêjlik usta-çırak ilişkisiyle öğrenilir: genç dengbêj ustasını dinleyerek kilamları ezberler ve onun söyleyişini sürdürür.'),
  ('65970ee9-2dfb-524e-b130-61cff68f505f', 'offline_10379', '"makam": Türk ve Kürt müziğinde ezgisel yapıyı belirleyen sistem.', 'Makam, ezginin hangi seslerden kurulacağını ve nasıl ilerleyeceğini belirleyen dizi ve kurallar sistemidir; ritmi değil ezgiyi düzenler.'),
  ('e7333f15-0ae5-594e-b3be-366230238b4b', 'offline_10423', '"tembûr": Yarsan/Ehl-i Hak geleneğinde kutsal sayılan telli saz.', 'Tembûr uzun saplı telli bir sazdır; Yarsan (Ehl-i Hak) inancında kutsal sayılır ve cem törenlerinde çalınır.'),
  ('5840fb72-4df1-5971-9170-8c40a337bf2b', 'offline_10480', '"botan ezgileri": Şırnak ve Cizre yöresinin ritmik ve makamsal müziği.', 'Botan ezgileri Şırnak ve Cizre yöresine aittir; ritmik ve makamsal yapısıyla öteki yöre tarzlarından ayrılır.'),
  ('74f436dc-cd10-53f9-9655-c003f190d9dc', 'offline_10498', '"Koma Amed": 90''larda Kürt müziğinde devrim yapan alternatif müzik grubu.', 'Koma Amed, Kürt müziğine modern çalgılar ve yeni düzenlemeler getiren alternatif bir müzik grubudur.'),
  ('199ad51d-6132-58a8-8436-49c6bedef930', 'offline_10566', '"nota": müziği kağıda dökmek için kullanılan evrensel işaretler.', 'Nota, seslerin yüksekliğini ve süresini yazıyla gösteren işaret sistemidir; böylece bir ezgi kâğıttan okunup çalınabilir.'),
  ('4efa354e-b0f0-5425-b4f5-085c3713c393', 'offline_10572', '"Hasan Cizrawî": erken dönem Kürt müziği kayıtlarını yapan dengbêj.', 'Hesen Cizrawî, Bağdat Radyosu''nun Kürtçe yayınlarında yıllarca kilam söyleyen Cizreli bir dengbêjdir.'),
  ('1d460377-37ec-5152-baa9-9436757d7e35', 'offline_10813', '"şabaş geleneği": müzisyenlere para atarak taltif etme adeti.', 'Şabaş, düğünlerde para ya da armağan verme geleneğidir; birçok yörede çalgıcılara verilen bahşişi de kapsar.'),
  ('59bfeddd-0c33-5014-9534-3dfbbe134c72', 'offline_10926', '"Mihemed Şêxo": Kürt halkının ulusal duygularını seslendiren ozan.', 'Mihemed Şêxo (1948–1989), Rojava kökenli bir sanatçıdır; tembûrla söylediği ulusal ve toplumsal şarkılarla tanınır.'),
  ('40ee687a-2280-566d-b7c9-d3659cf5cde1', 'offline_11068', '"behedînî ezgileri": Duhok ve Zaho yöresine has müzikal tarz.', 'Behdînî ezgileri Duhok ve Zaho çevresine (Behdînan) özgüdür; yöre ağzı ve kendine has ritimleriyle tanınır.'),
  ('c48de691-6c34-537d-8c95-93c5df996523', 'offline_11125', '"Şivan Perwer": Kürt müziğini uluslararası sahnelere taşıyan, sürgünde de üretmeyi sürdüren sanatçı.', 'Şivan Perwer, 1970''lerden beri Avrupa başta olmak üzere dünya sahnelerinde Kürtçe şarkılar söyledi; uzun yıllar sürgünde üretmeyi sürdürdü.'),
  ('1a33d5cf-9c5a-5047-9562-e1ef5f9bc716', 'offline_11136', '"ritim": müziğin temelini oluşturan düzenli vuruşlar.', 'Ritim, müzikte seslerin ve susların süre ve vurgu bakımından düzenlenmesidir; ezgiden farklı olarak seslerin yüksekliğini değil zamanlamasını belirler.'),
  ('9b118378-3bf5-58d1-8a3f-aaffb4706c67', 'offline_11294', '"erbane": halk müziğinde yaygın olarak çalınan zilli tef.', 'Erbane, kasnağına zil ya da halka takılan büyük bir teftir; dinî meclislerde ve halk müziğinde ritim için çalınır.'),
  ('8b73c0ae-af0a-598f-9776-02fa29944ee7', 'offline_12899', '"ademi merkeziyetçilik": yetkinin merkezden yerel birimlere dağıtılması.', 'Ademi merkeziyetçilikte karar yetkisinin bir bölümü merkezî yönetimden il, bölge ve belediyeler gibi yerel birimlere aktarılır.'),
  ('e953efd8-6f54-5ea2-a72d-d61c0ece7c4a', 'offline_13040', '"azınlık hakları": çoğunluktan farklı grupların korunması.', 'Azınlık hakları, sayıca az olan grupların dilini, dinini ve kültürünü çoğunluk karşısında korumayı amaçlar.'),
  ('12ffd15e-531d-5f5d-9ae0-3031d7c4fd55', 'offline_13122', '"barış hakkı": toplumun savaşsız yaşama dair evrensel hakkı.', 'Barış hakkı, bireylerin ve toplumların savaş ve şiddet tehdidi olmadan yaşama hakkıdır; insan haklarının "dayanışma hakları" kuşağında sayılır.'),
  ('51cd0509-a55f-543e-a98b-d1f1d69a354a', 'offline_13252', '"insan hakları": herkesin doğuştan sahip olduğu evrensel haklar.', 'İnsan hakları, kimsenin bağışlamasına bağlı olmadan her insanın doğuştan sahip olduğu evrensel haklardır; 1948 İnsan Hakları Evrensel Beyannamesi bunları sayar.'),
  ('26f36d38-a675-5830-99bf-b37e4434dc00', 'offline_13729', '"müzakere": sorunları diyalog yoluyla çözme yöntemi.', 'Müzakere, tarafların sorunları güç kullanmadan karşılıklı görüşme ve uzlaşmayla çözmeye çalışmasıdır.'),
  ('c7eb5be1-0bb8-5f79-841a-d4eb05e710ce', 'offline_13745', '"çoğulculuk": farklı kimlik ve inançların eşit kabulü.', 'Çoğulculuk, toplumdaki farklı kimlik, inanç ve görüşlerin bir arada ve eşit biçimde var olabilmesini savunur.'),
  ('4374f3ad-1c34-5e95-b4bc-408be1df17d9', 'offline_curated_20001', '"ergatîf" şu anlama gelir: geçişli fiillerin öznesini geçmiş zamanda bükümlü gösteren dilbilgisi yapısı.', 'Ergatif yapıda geçişli fiilin öznesi geçmiş zamanda bükümlü olur: "Min nan xwar" (Ben ekmek yedim) cümlesinde özne "ez" değil "min"dir.'),
  ('9acbc43f-b9d9-585e-8e54-eae85a2dfde6', 'offline_curated_20026', '"tewandin" şu anlama gelir: ad ya da zamirlerin cümledeki rolüne göre ek değiştirmesi.', 'Tewandin, ad ve zamirlerin cümledeki görevine göre biçim değiştirmesidir: "ez" bükümle "min", "jin" ise "jinê" olur.'),
  ('f9c06f28-dbe6-5d78-97e4-02d4b5949e98', 'offline_curated_20051', '"ezafe" şu anlama gelir: adları birbirine bağlayan dişil (a) ve eril (ê) tamlama ilişkisi.', 'Ezafe, adı kendisinden sonra gelen sözcüğe bağlar: dişil adlarda "-a" (mala min = benim evim), eril adlarda "-ê" (bavê min = benim babam).'),
  ('38fbf109-6c46-570f-83ed-9e1125dc2beb', 'offline_curated_20076', '"cînavkên tewandî" şu anlama gelir: büküm (tewandin) almış "min, te, wî, wê, me, we, wan" gibi zamirler.', 'Bükümlü zamirler (min, te, wî, wê, me, we, wan) şimdiki zamanlı geçişli cümlede nesne, geçmiş zamanlı geçişli cümlede özne olur: "Ez wî dibînim" (Onu görüyorum), "Min ew dît" (Onu gördüm).'),
  ('2b5cf310-88bb-5a54-a88b-d65c756d14bd', 'offline_curated_20126', '"lêkera gerguhêz" şu anlama gelir: anlamını tamamlamak için bükümlü nesneye ihtiyaç duyan fiiller.', 'Geçişli fiiller nesne alabilir: "xwarin" (yemek) ile neyin yendiği söylenebilir ("Ez nan dixwim"); "hatin" (gelmek) ise geçişsizdir ve nesne almaz.'),
  ('b3d2fac6-10e1-5df6-8cd6-7bcf72f3ac9c', 'offline_curated_20151', '"rênivîsa Hawarê" şu anlama gelir: Celadet Bedirxan''ın hazırladığı Latin harfli Kürt alfabesi sistemi.', 'Hawar yazımı, Celadet Alî Bedirxan''ın 1932''de Hawar dergisiyle yaydığı 31 harfli Latin Kurmancî alfabesidir; bugün yaygın biçimde kullanılan yazımdır.'),
  ('3a4274cb-5e1a-5101-b418-3c3ac192d9e1', 'offline_curated_20176', '"cînavkên kesane" şu anlama gelir: kişiler için kullanılan "ez, tu, ew, em, hûn, ew" gibi göstericiler.', 'Kişi zamirleri (ez, tu, ew, em, hûn, ew) bükümsüz yalın hâldir; şimdiki zamanda özne olarak kullanılır: "Ez diçim" (Gidiyorum).'),
  ('561527f4-5679-5fe3-83c2-ff90010d2b87', 'offline_curated_20201', '"dema borî ya dûr" şu anlama gelir: çok uzak bir geçmişte olan eylemi gösteren fiil yapısı.', 'Uzak geçmiş (dema borî ya dûr), geçmişteki bir eylemden önce tamamlanmış eylemi anlatır: "Ez hatibûm" (Gelmiştim), "Min xwaribû" (Yemiştim).'),
  ('508123b7-3a59-5da3-97d5-4e5567c80bc4', 'offline_curated_20226', '"paşgirên tewandinê" şu anlama gelir: adların bükümünde yer alan "-î, -ê, -an" gibi ekler.', 'Büküm ekleri adın cümledeki görevine göre eklenir: eril tekilde "-î" (mêrî), dişil tekilde "-ê" (jinê), çoğulda "-an" (zarokan).'),
  ('d5d1dc8d-428e-5d48-865f-1693c1ce35ed', 'offline_curated_20251', '"Melayê Cizîrî" şu anlama gelir: felsefî ve tasavvufî divanıyla tanınan büyük klasik şair.', 'Melayê Cizîrî (16.–17. yy), divanında tasavvufi aşkı ve felsefi düşünceyi işleyen klasik Kurmancî şairidir; Cizre''de yaşamıştır.'),
  ('cec40864-20c2-5066-90b8-c844e70fe42a', 'offline_curated_20276', '"Feqiyê Teyran" şu anlama gelir: "Şêx Sen''an" eseri ve kuşlarla konuşmasıyla tanınan klasik şair.', 'Feqiyê Teyran, "teyr" (kuş) sözcüğünden gelen adını kuşlarla konuştuğu söylencesinden alır; Şêx Sen''an manzum hikâyesiyle tanınır.'),
  ('89461275-3ebd-58bb-b783-6b4bc39f993b', 'offline_curated_20326', '"Melayê Bateyî" şu anlama gelir: ilk Kürt Mevlidini Kurmancî lehçesinde yazan şair.', 'Melayê Bateyî, Kurmancî yazdığı Mewlûda Kurdî ile tanınır; bu mevlit bugün de dinî toplantılarda okunur. Yaşadığı dönem konusunda farklı görüşler vardır.'),
  ('86d45d6f-a690-58df-93ed-b0557ab297a5', 'offline_curated_20375', '"Cegerxwîn" şu anlama gelir: modern Kürt şiirini yeni bir aşamaya taşıyan devrimci ve toplumcu şair.', 'Cegerxwîn, klasik biçimleri kullanmakla birlikte şiirin konusunu tasavvuftan halkın yoksulluğuna, haklarına ve özgürlüğüne çevirdi.'),
  ('3bad7ce2-4c0c-58e9-8dc9-06b08c8a0808', 'offline_curated_20426', '"Mehmed Uzun" şu anlama gelir: derin ve edebî diliyle Kürt romanında devrim yapan modern Kürt romancısı.', 'Mehmed Uzun (1953–2007), Siya Evînê ve Bîra Qederê gibi romanlarıyla Kurmancî romanı edebî dil ve derinlik açısından yeni bir düzeye taşıdı.'),
  ('e2383ed2-23aa-56f5-b7ce-60e7a686af4c', 'offline_curated_20451', '"şevbêrkên wêjeyî" şu anlama gelir: klasik ve modern şiir ile hikâyelerin okunduğu gece toplantıları.', 'Edebî şevbêrkler, kış gecelerinde toplanılıp klasik ve modern şiirlerin, hikâyelerin okunduğu sohbet toplantılarıdır; sözlü edebiyatın aktarıldığı yerlerdir.'),
  ('d8c3d439-b1cc-5988-8d8b-368611243b0c', 'offline_curated_20476', '"Helbesta Azad" şu anlama gelir: ölçüsüz ve kafiyesiz, ağırlığını sözcüğe veren modern şiir yöntemi.', 'Serbest şiir (Helbesta Azad) ölçü ve kafiye zorunluluğunu kaldırır; kafiye kullanılabilir ama şart değildir, anlam ve etki sözcük seçimiyle kurulur.'),
  ('e0a361e9-03d5-53f1-8590-b2d2b4226d66', 'offline_curated_20501', '"Împaratoriya Medî" şu anlama gelir: bazı Kürt tarih anlatılarında atalara bağlanan, Zagros dağlarındaki antik güç.', 'Medler, MÖ 7.–6. yüzyılda Zagros merkezli bir imparatorluk kurdu; bazı Kürt tarih anlatıları Kürtlerin kökenini Medlere bağlar.'),
  ('cf1d8cee-f9c5-5683-bb7e-8683c546db06', 'offline_curated_20526', '"Dewleta Merwaniyan" şu anlama gelir: merkezi Amed ve çevresi olan ortaçağ Kürt hanedanı.', 'Mervanîler, 10. yüzyılın sonundan 1085''e kadar Amed ve Farqîn (Silvan) çevresinde hüküm süren ortaçağ Kürt hanedanıdır.'),
  ('566fc3c0-6b02-5384-9876-6ec99961c911', 'offline_curated_20625', '"Selaheddînê Eyûbî" şu anlama gelir: Kudüs''ü Haçlılardan geri alan ve Eyyubi hanedanını kuran büyük Kürt önder.', 'Kürt kökenli Selahaddin Eyyubi, 1171''de Eyyubi yönetiminin temelini attı; 1187''de Hıttin zaferinin ardından Kudüs''ü Haçlılardan aldı.'),
  ('a97da665-c2f8-5802-a724-f3b2b8928578', 'offline_curated_20679', '"Rojnameya Kurdistan": 1898''de Kahire''de Mîqdat Mîdhad Bedirxan tarafından çıkarılan ilk Kürtçe gazete.', 'Kurdistan gazetesi 22 Nisan 1898''de Kahire''de Mikdat Mithat Bedirxan tarafından yayımlandı; ilk Kürtçe gazete olduğu için bu tarih Kürt basın günü sayılır.'),
  ('11637dbd-8ca6-541f-b8b6-783aaa304c72', 'offline_curated_20701', '"Mîrgeha Erdelanê" şu anlama gelir: merkezi Sine olan, doğudaki kadim bir Kürt beyliği.', 'Erdelan Beyliği''nin merkezi Sine (Senendec) idi; Doğu Kürdistan''da yüzyıllarca süren bir beylikti ve Mestûre Erdelan bu beyliğin tarihini yazdı.'),
  ('b6d66019-4aad-59dd-b116-a42bef42c3a4', 'offline_curated_20750', '"çiyayên Zagrosê" şu anlama gelir: Kürtlerin ülkesinin doğal sınırını oluşturan büyük ve sarp sıradağlar.', 'Zagros Dağları kuzeybatı–güneydoğu doğrultusunda uzanan sarp bir sıradağdır; Kürt coğrafyasının doğal sınırlarından ve omurgasından biridir.'),
  ('1e1d5a70-f478-502d-9121-5d4f129a573a', 'offline_curated_20826', '"Çiyayê Cûdî" şu anlama gelir: inanışa göre Nuh Peygamber''in gemisinin üzerine oturduğu kutsal dağ.', 'Cudi Dağı Şırnak''tadır; İslami gelenekte ve bazı eski kaynaklarda Nuh''un gemisinin oturduğu yer olarak anılır.'),
  ('13f09861-251b-5ac7-8edd-b8c74a5c17a1', 'offline_curated_20851', '"Girê Mirazan" şu anlama gelir: Riha (Urfa) yakınlarındaki, insanlığın en eski tapınak yeri.', 'Göbeklitepe (Girê Mirazan), Urfa yakınında yaklaşık 11.600 yıl öncesine uzanan anıtsal yapılarıyla bilinen Neolitik bir alandır; yapılar törensel işlevlerle ilişkilendirilir ve bilinen en eski tapınak yapılarından sayılır.'),
  ('34705932-2632-59da-a12f-aca9f2087b8a', 'offline_curated_20901', '"Çiyayê Sîpanê" şu anlama gelir: Van Gölü''nün kuzeyindeki yüksek ve karlı volkanik dağ.', 'Süphan Dağı (Çiyayê Sîpanê), Van Gölü''nün kuzey kıyısında yükselen sönmüş bir volkandır; Türkiye''nin en yüksek dağlarındandır.'),
  ('f97a2f0c-70ac-53db-9565-7d29204ca7ce', 'offline_curated_20926', '"Geliyê Zapê" şu anlama gelir: coşkun Zap suyunun güneye doğru aktığı derin ve dar vadi.', 'Zap Vadisi (Geliyê Zapê), Hakkari dağlarından güneye akan Büyük Zap''ın açtığı derin ve dar vadidir; Zap sonunda Dicle''ye karışır.'),
  ('bac807de-18f9-55ab-9d60-d74dbf95b631', 'offline_curated_20951', '"Heskîf" şu anlama gelir: Dicle kıyısındaki, eşsiz mağaralarıyla bilinen kadim tarihî kent.', 'Heskîf (Hasankeyf), Dicle kıyısında kayalara oyulmuş binlerce mağara konutuyla bilinir; eski kentin büyük bölümü Ilısu Barajı suları altında kaldı.'),
  ('43bcb411-91b7-5c77-aeb3-b030a5ec2691', 'offline_curated_20976', '"Qerejdax" şu anlama gelir: Amed ovasını Riha ovasından ayıran bazaltik volkanik dağ.', 'Karacadağ (Qerejdax), Diyarbakır ile Urfa ovaları arasında uzanan geniş bir kalkan volkanıdır; bazalt lavları iki ovayı birbirinden ayırır.'),
  ('ea1f3a69-b8c9-5d3a-8671-2b838c14da19', 'offline_curated_21001', '"Sazîbûna Dengbêjiyê" şu anlama gelir: dengbêjlerin stran ve kilamlarıyla yürüyen, dili ve tarihi koruyan kale.', 'Dengbêjlik, yazının yaygın olmadığı dönemlerde tarihi, savaşları ve aşkları kilamlarla kuşaktan kuşağa aktararak dili ve hafızayı korudu.'),
  ('c2471c74-2b7e-560a-a16b-2076a08b536f', 'offline_curated_21076', '"Govenda Kurdî" şu anlama gelir: el ele tutuşarak ve dayanışma ruhuyla oynanan toplu halk dansı.', 'Govend, katılanların el ele ya da omuz omuza tutuşup halka veya sıra hâlinde oynadığı toplu halk dansıdır.'),
  ('278b149d-3a62-5cdd-aecd-02abffe46efd', 'offline_curated_21101', '"çanda koçeriyê" şu anlama gelir: yayla ve germiyan arasındaki, Kürt kültürünü zenginleştiren kadim yaşam biçimi.', 'Göçerlikte sürüler yazın serin yaylalara (zozan), kışın ılık alçak yerlere (germiyan) götürülür; yaşam bu mevsimlik döngüye göre kurulur.'),
  ('63827b58-2d46-5781-9f67-76ca544b1ddd', 'offline_curated_21176', '"Destana Memê Alan" şu anlama gelir: Xanî''nin Mem û Zîn''inin temelini oluşturan Kürt ulusal destanı.', 'Ehmedê Xanî 1692''de yazdığı Mem û Zîn''de sözlü Memê Alan destanından yararlandı ve onu ulusal bir aşk mesnevisine dönüştürdü.'),
  ('bcb4471c-f216-5c5b-b2d3-6b66c383f370', 'offline_curated_21200', '"hewran" şu anlama gelir: diğer giysilerin üstüne giyilen uzun üstlük/aba.', 'Hewran, öteki giysilerin üstüne giyilen uzun dış giysidir; en üst kat olarak giyilir.'),
  ('80e0767c-3872-55cb-9f40-e9fafa8be3b6', 'offline_curated_21226', '"şevbêrk" şu anlama gelir: halk masalları ve bilmecelerin anlatıldığı kış gecesi toplantıları.', 'Şevbêrk, uzun kış gecelerinde bir evde toplanılıp masal, bilmece ve kilamlarla vakit geçirilen toplantıdır.'),
  ('dee39536-39d7-5f58-9905-c487d6f39943', 'offline_curated_21251', '"tembûr" şu anlama gelir: özellikle dinî meclislerde çalınan, Yarsan/Ehl-i Hak geleneğinde kutsal sayılan telli çalgı.', 'Tembûr uzun saplı telli bir sazdır; Yarsan (Ehl-i Hak) inancında kutsal sayılır ve cem törenlerinde çalınır.'),
  ('b9ccc63f-ac26-59b8-b4d8-625105ec4190', 'offline_curated_21276', '"erbane" şu anlama gelir: Kürt dinî ve halk müziğinde önemli yeri olan zilli vurmalı çalgı.', 'Erbane, kasnağına zil ya da halka takılan büyük bir teftir; tekke ve dinî meclislerde zikre ve halk müziğinde ritme eşlik eder.'),
  ('a7cb2c9b-b992-563f-9842-87e1a55ff705', 'offline_curated_21301', '"bilûr" şu anlama gelir: hüzünlü ve lirik sesiyle bilinen çoban üflemeli çalgısı.', 'Bilûr, çobanların taşıdığı ağızdan üflemeli kaval türü çalgıdır; yumuşak ve hüzünlü sesiyle tanınır.'),
  ('b9ae7f7e-1b22-598a-9e8a-359e757917e0', 'offline_curated_21326', '"lîrîka klaman" şu anlama gelir: aşk ve savaş hikâyelerini anlatan dengbêj kilamlarının şiirsel yapısı.', 'Dengbêj kilamları aşk ve savaş hikâyelerini şiirsel bir dille, tekrarlarla ve uzun ezgili söyleyişle anlatır.'),
  ('3d29e580-9e55-56fc-b738-071562af70cf', 'offline_curated_21351', '"Şakiro" şu anlama gelir: "Dengbêjlerin Şahı" diye bilinen, eşsiz sese sahip büyük dengbêj.', 'Şakiro (1936–1996), güçlü sesi ve geniş kilam dağarcığıyla dengbêjler arasında "dengbêjlerin şahı" diye anılır.'),
  ('d72e8f29-7c93-5925-81c2-92e35fccad60', 'offline_curated_21376', '"Hasan Cizrawî" şu anlama gelir: Botan yöresinin kilamlarını kaydeden, klasik Kurmancî müziğinin direklerinden biri.', 'Hesen Cizrawî, Bağdat Radyosu''nun Kürtçe yayınlarında söylediği Botan kilamlarıyla tanınan Cizreli bir dengbêjdir.'),
  ('f0b35b33-3d94-54a1-a028-e7ca04b782b2', 'offline_curated_21401', '"Meryem Xan" şu anlama gelir: sesini plağa kaydeden ilk Kürt kadın şarkıcı.', 'Meryem Xan (1904–1949), 1920''lerde ve 1930''larda plak dolduran ilk Kürt kadın şarkıcılardandır.'),
  ('8d89bae8-ac07-5b59-9ac8-b1dabdf2c113', 'offline_curated_21451', '"lawik" şu anlama gelir: çoğunlukla aşk ve hasret üzerine söylenen lirik dengbêjlik kilamı.', 'Lawik, dengbêjlik geleneğinde çoğunlukla aşkı, hasreti ve ayrılığı işleyen lirik kilam türüdür.'),
  ('bb4d417e-241e-504f-ab15-882fe1ddb986', 'offline_curated_21475', '"heyran" şu anlama gelir: özellikle kadınların söylediği Serhat yöresi aşk kilamları.', 'Heyranok (heyran), Serhed yöresinde çoğunlukla kadınların söylediği, sevdiğine seslenen aşk kilamlarıdır.'),
  ('4871a5b2-2479-536f-a069-d310f26bb12f', 'offline_curated_21601', '"ademi-merkeziyet" şu anlama gelir: iktidarın merkezden bölgelere ve özerk yönetimlere dağıtılması.', 'Ademi merkeziyette yetki merkezî yönetimde toplanmaz; bölgelere ve yerel yönetimlere dağıtılır.'),
  ('523101c4-385b-54a2-863e-4a8af327459f', 'offline_curated_21651', '"pirrengî" şu anlama gelir: toplumdaki bütün farklı kimliklerin korunması ve kabul edilmesi ilkesi.', 'Pirrengî (çoğulculuk), toplumdaki farklı kimliklerin bir arada var olmasını ve eşit biçimde tanınmasını savunan ilkedir.'),
  ('b9f95b18-db36-585c-a9b7-0c9be820e5c3', 'offline_curated_21676', '"demokrasiya rasterast" şu anlama gelir: halkın temsilciler olmadan karar verdiği yönetim biçimi.', 'Doğrudan demokraside halk kararları temsilci seçmeden kendisi alır; meclislerde ya da halk oylamalarında doğrudan oy kullanır.'),
  ('872e482d-52cc-5bb4-a208-d2f4eb6d0737', 'offline_tf_siy_0031', 'Evet. Aynı alandan bir başka kavram: "dadgehkirina dadperwer" şu anlama gelir: herkesin açık, tarafsız ve makul sürede yargılanma hakkı.', 'Doğru. Cinsiyet kotası (kotaya zayendî), kurumlarda ve seçilmiş organlarda kadınların belirli bir orandan az temsil edilmemesi için asgari bir pay belirlenmesidir.'),
  ('f4e67d62-aea8-56a1-88e8-878db7b034d9', 'ds_cografya_0199', 'Koordinat ağı (graticule), haritada enlem ve boylamları gösteren çizgilerdir. İzolin çizgisi ise yüksekliği gösterir.', 'Koordinat ağı (graticule), haritada enlem (paralel) ve boylam (meridyen) çizgilerinin oluşturduğu ağdır. İzolin ise eş değerli noktaları birleştiren çizgidir; eş yükselti eğrisi bunun yükseklik için kullanılan türüdür.'),
  ('97a7c8aa-a36e-5e01-9225-ea3c1c6ea478', 'cinema_0005', 'Vitaphone sistemiyle konuşma ve şarkı görüntüyle eşzamanlı verildi; bu, sessiz dönemin birkaç yıl içinde kapanmasına yol açtı. Renkli süreç ve uzun metraj animasyon yenilikleri 1930''ların sonunu bekledi.', 'Vitaphone sistemiyle şarkılar ve bazı konuşmalar görüntüyle eşzamanlı verildi. Ses ile görüntünün eşzamanlı verilmesi, sessiz filmden sesli filme geçişi hızlandırdı.'),
  ('da5dbcb8-c9de-5ce7-8a88-af9a272a9675', 'ders_2026_10_01_0055', '"Dilşad" sevinç ve neşedir.', '"Dilşad" sevinçli, neşeli demektir; "dil" (gönül) ve "şad" (sevinçli) sözcüklerinden oluşur. "Xemgîn" ise üzgün demektir.'),
  ('c1f8e390-1284-5240-9e23-1f3e3e35c12e', 'ds_cografya_0205', 'İç göç, bir ülke içinde, örneğin köyden şehre göç etmek anlamına gelir. Dış göç başka bir ülkeye gitmektir; geçici ve döngüsel göç ise geçicidir.', 'İç göç, bir ülkenin sınırları içinde yapılan göçtür; köyden şehre ve şehirler arası göç bunun örnekleridir. Dış göç başka bir ülkeye yapılır; geçici ve döngüsel göç ise belirli bir süre ya da mevsim için yapılır ve kalıcı yerleşme amacı taşımaz.'),
  ('c01560a2-2d59-554b-91c0-28ff7cc365ed', 'offline_tf_siy_0018', 'Hayır — bu tanım "muxalefeta civakî" kavramına ait; "muxalefeta demokratîk", iktidarı silaha başvurmadan, hukuk içinde eleştirmedir.', 'Yanlış. Demokratik muhalefeti yalnız partiler değil; sivil toplum kuruluşları, sendikalar ve toplumsal hareketler de barışçıl ve hukuki yollarla yürütebilir.');
